def rotate_items(items, k):
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be a nonnegative integer")
    if k < 0:
        raise ValueError("k must be nonnegative")

    values = list(items)
    if not values:
        return []

    shift = k % len(values)
    if shift == 0:
        return values

    return values[-shift:] + values[:-shift]

def interleave(left, right):
    if len(left) != len(right):
        raise ValueError("left and right must be equally sized")
    result = []
    for left_item, right_item in zip(left, right):
        result.extend((left_item, right_item))
    return result

def sort_labels(labels):
    if labels is None:
        raise ValueError("labels must be an iterable")

    distinct = {}
    for label in labels:
        if not isinstance(label, str):
            raise TypeError("labels must contain strings")
        distinct.setdefault(label.lower(), label)

    return tuple(distinct[key] for key in sorted(distinct))

def find_products(products, query):
    if not isinstance(query, str):
        raise TypeError("query must be a string")

    matches = []
    query_key = query.casefold()

    for product in products:
        if not isinstance(product, dict):
            raise TypeError("each product must be a dictionary")
        if not isinstance(product.get("name"), str):
            raise TypeError("product name must be a string")
        if "score" not in product:
            raise KeyError("product must contain a score")

        score = product["score"]
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError("product score must be numeric")

        if query_key in product["name"].casefold():
            matches.append(product)

    return sorted(matches, key=lambda product: product["score"], reverse=True)

def group_words(words):
    groups = {}
    order = []

    for word in words:
        if not isinstance(word, str):
            raise TypeError("each word must be a string")
        if not word:
            raise ValueError("words must not be empty")
        key = word[0].lower()
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(word)

    if not order:
        return None

    return tuple((key, tuple(groups[key])) for key in order)

def nearest_date(dates, target):
    import datetime
    import re

    pattern = re.compile(r"^\d{4}-\d{2}-\d{2}$")

    def parse(value):
        if not isinstance(value, str):
            raise TypeError("dates must be strings in YYYY-MM-DD form")
        if not pattern.fullmatch(value):
            raise ValueError("dates must use YYYY-MM-DD form")
        try:
            return datetime.date.fromisoformat(value)
        except ValueError:
            raise ValueError("invalid date")

    target_date = parse(target)
    nearest = None
    nearest_distance = None

    for value in dates:
        value_date = parse(value)
        distance = abs((value_date - target_date).days)
        if nearest is None or distance < nearest_distance:
            nearest = value
            nearest_distance = distance

    return nearest

def median_value(values):
    ordered = sorted(values)
    count = len(ordered)
    if count == 0:
        return None
    middle = count // 2
    if count % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

def merge_ranges(ranges):
    if ranges is None:
        raise TypeError("ranges must be an iterable of ranges")

    normalized = []
    for item in ranges:
        try:
            start, end = item
        except (TypeError, ValueError):
            raise ValueError("each range must contain exactly two values") from None

        if start > end:
            raise ValueError("range start must not exceed range end")

        normalized.append((start, end))

    if not normalized:
        return None

    normalized.sort(key=lambda interval: interval[0])
    merged = [normalized[0]]

    for start, end in normalized[1:]:
        previous_start, previous_end = merged[-1]
        if start <= previous_end:
            if end > previous_end:
                merged[-1] = (previous_start, end)
        else:
            merged.append((start, end))

    return tuple(merged)

def shortest_path(graph, start, goal):
    from collections import deque

    if start == goal:
        return (start,)

    queue = deque([start])
    previous = {start: None}

    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, ()):
            if neighbor in previous:
                continue
            previous[neighbor] = node
            if neighbor == goal:
                path = []
                current = goal
                while current is not None:
                    path.append(current)
                    current = previous[current]
                return tuple(reversed(path))
            queue.append(neighbor)

    return None

def topological_order(nodes, edges):
    node_list = []
    node_set = set()

    for node in nodes:
        if node not in node_set:
            node_set.add(node)
            node_list.append(node)

    adjacency = {node: [] for node in node_list}
    indegree = {node: 0 for node in node_list}

    for source, destination in edges:
        if source not in node_set or destination not in node_set:
            raise ValueError("edges must reference supplied nodes")
        adjacency[source].append(destination)
        indegree[destination] += 1

    available = [node for node in node_list if indegree[node] == 0]
    result = []

    while available:
        node = available.pop(0)
        result.append(node)

        for destination in adjacency[node]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                available.append(destination)

    if len(result) != len(node_list):
        raise ValueError("graph must be acyclic")

    return result
